reads.command:
uv run python -c "import numpy as np, pandas as pd; train=pd.read_csv('train.csv'); X=train.drop(columns=['target']).to_numpy(float); y=train['target'].to_numpy(int); rng=np.random.default_rng(5); idx=rng.permutation(len(y)); split=int(len(y)*0.8); tr,va=idx[:split],idx[split:]; Xtr,Xva=X[tr],X[va]; ytr,yva=y[tr],y[va]; qs=np.linspace(5,95,19); thresholds=[np.unique(np.percentile(Xtr[:,j],qs)) for j in range(Xtr.shape[1])]; ypm=ytr*2-1; w=np.full(len(ytr),1/len(ytr)); models=[]; 
for _ in range(30):
    best=None
    for j in range(Xtr.shape[1]):
        col=Xtr[:,j]
        for t in thresholds[j]:
            pred=np.where(col>t,1,-1)
            err=w[pred!=ypm].sum()
            pol=1
            if err>0.5:
                err=1.0-err; pol=-1
            if best is None or err<best[0]:
                best=(err,j,float(t),pol)
    err,j,t,pol=best
    err=np.clip(err,1e-9,1-1e-9)
    alpha=0.5*np.log((1-err)/err)
    pred=pol*np.where(Xtr[:,j]>t,1,-1)
    w*=np.exp(-alpha*ypm*pred)
    w/=w.sum()
    models.append((alpha,j,t,pol))
scores=np.zeros(len(yva));
for alpha,j,t,pol in models:
    scores+=alpha*pol*np.where(Xva[:,j]>t,1,-1)
pred=(scores>0).astype(int); print(f'adaboost30\t{(pred==yva).mean():.6f}')"

